/*
 * Minimal RGBA PNG writer (no dependencies) — art-plan step B.
 * Renders art/.art/generate.js output into art/src/sheet-draft.png, which the Aseprite MCP then
 * imports, quantizes to the game palette and exports as art/export/sheet.png. The draft is a
 * build product (regenerated by `node render.js`); the .aseprite and the export are committed.
 */
"use strict";
const fs = require("fs");
const path = require("path");
const zlib = require("zlib");

function crc32(buf) {
  let c, table = crc32.table || (crc32.table = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n++) { c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c; }
    return t;
  })());
  c = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) c = table[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
}

function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
}

function writePng(file, width, height, rgba) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0); ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; ihdr[9] = 6; // 8-bit RGBA
  const stride = width * 4;
  const raw = Buffer.alloc((stride + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[y * (stride + 1)] = 0; // filter: none
    rgba.copy(raw, y * (stride + 1) + 1, y * stride, (y + 1) * stride);
  }
  const png = Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),
    chunk("IHDR", ihdr),
    chunk("IDAT", zlib.deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
  fs.writeFileSync(file, png);
  return png.length;
}

const pack = JSON.parse(fs.readFileSync(path.join(__dirname, "pixels.json"), "utf8"));
const rgba = Buffer.alloc(pack.width * pack.height * 4); // transparent everywhere
const hexCache = new Map();
function rgb(hex) {
  if (!hexCache.has(hex)) hexCache.set(hex, [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)]);
  return hexCache.get(hex);
}
for (const r of pack.rects) {
  r.frames.forEach((pixels, fi) => {
    for (const [x, y, hex] of pixels) {
      const py = r.y + fi * r.h + y;
      const px = r.x + x;
      if (px < 0 || py < 0 || px >= pack.width || py >= pack.height) { console.warn("outside sheet:", r.name, px, py); continue; }
      const [R, G, B] = rgb(hex);
      const o = (py * pack.width + px) * 4;
      rgba[o] = R; rgba[o + 1] = G; rgba[o + 2] = B; rgba[o + 3] = 255;
    }
  });
}
fs.mkdirSync(path.join(__dirname, "..", "src"), { recursive: true });
const bytes = writePng(path.join(__dirname, "..", "src", "sheet-draft.png"), pack.width, pack.height, rgba);
console.log("wrote art/src/sheet-draft.png", pack.width + "x" + pack.height, bytes + " bytes");
